using System;using System.Windows;using System.Windows.Interop;using System.Windows.Media;using System.Runtime.InteropServices;
internal static class SuitePlacement {
 // Bounds are in physical pixels, so a mixed-DPI desktop uses the owning monitor's scale.
 internal static (int Left,int Top,int Width,int Height,bool Above) Bounds(int workLeft,int workTop,int workRight,int workBottom,int widgetLeft,int widgetTop,int widgetWidth,double scale){int gap=Math.Max(1,(int)Math.Round(12*scale));int width=Math.Min(widgetWidth,Math.Max(1,workRight-workLeft-2*gap));int height=Math.Min((int)Math.Round(460*scale),Math.Max(1,workBottom-workTop-2*gap));bool above=widgetTop-gap-height>=workTop+gap;int top=above?widgetTop-gap-height:workBottom-gap-height;int left=Math.Clamp(widgetLeft,workLeft+gap,Math.Max(workLeft+gap,workRight-gap-width));return(left,top,width,height,above);}
 public static void PrepareWidget(Window widget){var hwnd=new WindowInteropHelper(widget).Handle;if(hwnd==IntPtr.Zero||!GetWindowRect(hwnd,out var r))return;var info=new Info{Size=Marshal.SizeOf<Info>()};if(!GetMonitorInfo(MonitorFromWindow(hwnd,2),ref info))return;var dpi=VisualTreeHelper.GetDpi(widget);double work=(info.Work.Bottom-info.Work.Top)/dpi.DpiScaleY;if(work<636)return;double height=Math.Max(1,Math.Min(600,work-496));if(height<100)height=Math.Max(1,(work-36)*.25);widget.Height=height;widget.UpdateLayout();int h=(int)Math.Round(height*dpi.DpiScaleY);SetWindowPos(hwnd,IntPtr.Zero,r.Left,info.Work.Bottom-(int)Math.Round(12*dpi.DpiScaleY)-h,r.Right-r.Left,h,0x14);}
 public static void Above(Window widget,Window panel){var wh=new WindowInteropHelper(widget).Handle;var ph=new WindowInteropHelper(panel).EnsureHandle();if(!GetWindowRect(wh,out var r))return;var info=new Info{Size=Marshal.SizeOf<Info>()};if(!GetMonitorInfo(MonitorFromWindow(wh,2),ref info))return;var dpi=VisualTreeHelper.GetDpi(widget);var bounds=Bounds(info.Work.Left,info.Work.Top,info.Work.Right,info.Work.Bottom,r.Left,r.Top,r.Right-r.Left,dpi.DpiScaleY);panel.Width=bounds.Width/dpi.DpiScaleX;panel.Height=bounds.Height/dpi.DpiScaleY;panel.UpdateLayout();SetWindowPos(ph,IntPtr.Zero,bounds.Left,bounds.Top,bounds.Width,bounds.Height,0x14);}
 public static bool IsPlaced(Window widget,Window? panel){if(panel==null||!GetWindowRect(new WindowInteropHelper(widget).Handle,out var w)||!GetWindowRect(new WindowInteropHelper(panel).Handle,out var p))return false;var info=new Info{Size=Marshal.SizeOf<Info>()};if(!GetMonitorInfo(MonitorFromWindow(new WindowInteropHelper(widget).Handle,2),ref info))return false;var expected=Bounds(info.Work.Left,info.Work.Top,info.Work.Right,info.Work.Bottom,w.Left,w.Top,w.Right-w.Left,VisualTreeHelper.GetDpi(widget).DpiScaleY);return Math.Abs(p.Left-expected.Left)<=2&&Math.Abs(p.Top-expected.Top)<=2&&Math.Abs(p.Right-p.Left-expected.Width)<=2&&Math.Abs(p.Bottom-p.Top-expected.Height)<=2;}
 public static bool IsAbove(Window widget,Window? panel){if(panel==null||!GetWindowRect(new WindowInteropHelper(widget).Handle,out var w)||!GetWindowRect(new WindowInteropHelper(panel).Handle,out var p))return false;var dpi=VisualTreeHelper.GetDpi(widget);return Math.Abs(w.Left-p.Left)<=1&&Math.Abs(w.Right-p.Right)<=1&&Math.Abs(w.Top-p.Bottom-12*dpi.DpiScaleY)<=2;}
 [StructLayout(LayoutKind.Sequential)]struct Rect{public int Left,Top,Right,Bottom;}
 [StructLayout(LayoutKind.Sequential)]struct Info{public int Size;public Rect Monitor,Work;public uint Flags;}
 [DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr hwnd,out Rect r);
 [DllImport("user32.dll")]static extern IntPtr MonitorFromWindow(IntPtr hwnd,uint flags);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool GetMonitorInfo(IntPtr hwnd,ref Info info);
 [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr hwnd,IntPtr after,int x,int y,int width,int height,uint flags);
}
